/**
 * Builds tests/pdf-sample.pdf: three pages, each with its own known sentence, and one PNG
 * picture on page 2 (for the image-saving checks). Generated by headless Chromium so the
 * fixture is reproducible from source; the PDF itself is committed.
 *
 *   node tests/make-pdf-fixture.mjs
 */
import path from 'path';
import { fileURLToPath } from 'url';
import puppeteer from 'puppeteer';

const here = path.dirname(fileURLToPath(import.meta.url));
// A 24x24 PNG with a solid orange square, drawn by a canvas at build time.
const html = `<!doctype html><html><head><meta charset="utf-8"><style>
  body { font-family: Georgia, serif; font-size: 18px; margin: 2cm; }
  .p { page-break-after: always; }
  .p:last-child { page-break-after: auto; }
  h1 { font-size: 26px; }
</style></head><body>
  <div class="p"><h1>Chapter One</h1><p>TypoZen PDF fixture, page one: the lantern keeper counted gulls.</p></div>
  <div class="p"><h1>Chapter Two</h1><p>Page two holds a picture below this line.</p><img id="pic" width="240" height="160"></div>
  <div class="p"><h1>Chapter Three</h1><p>TypoZen PDF fixture, page three: the harbour was quiet at dawn.</p></div>
  <script>
    const c = document.createElement('canvas'); c.width = 240; c.height = 160;
    const g = c.getContext('2d'); g.fillStyle = '#E8732A'; g.fillRect(0, 0, 240, 160);
    g.fillStyle = '#1E3A5F'; g.fillRect(40, 30, 160, 100);
    document.getElementById('pic').src = c.toDataURL('image/png');
  </script>
</body></html>`;

const browser = await puppeteer.launch({ headless: 'new' });
try {
    const page = await browser.newPage();
    await page.setContent(html, { waitUntil: 'load' });
    await page.pdf({ path: path.join(here, 'pdf-sample.pdf'), format: 'A5', printBackground: true, outline: true, tagged: true });
    console.log('wrote tests/pdf-sample.pdf');
} finally { await browser.close(); }
